<script setup>
import { ref, onMounted, onUnmounted } from "vue";
import { gsap } from "gsap";

const flowersRef = ref(null);
let masterTimeline;

function getBranches(position) {
  if (!flowersRef.value) return [];
  return Array.from(
    flowersRef.value.querySelectorAll(
      position ? `[id^=BranchGroup-${position}]` : "[id^=BranchGroup]"
    )
  );
}

function getSmallBranches() {
  if (!flowersRef.value) return [];
  return Array.from(
    flowersRef.value.querySelectorAll("[id^=smallbranch-group]")
  );
}

function mainSetUp() {
  const tl = gsap.timeline();
  tl.set("[id^=petal-]", { fill: "#e5d081" })
    .set(["[id^=flower-]", "[id^=bud-]", "[id^=bloom-]"], {
      scale: 0,
      transformOrigin: "left left",
    })
    .set(getBranches("left"), { transformOrigin: "bottom left" })
    // .set(getBranches("right"), { transformOrigin: "bottom right" })
    // .set(getBranches("bottom"), { transformOrigin: "bottom center" })
    .set("#BranchGroup-left-1", { transformOrigin: "0% 20%" })
    .set("#BranchGroup-right-4", { transformOrigin: "100% 20%" }) //增加节点，动态修改
    .set(getBranches(), { scale: 0 })
    .set(".container", { autoAlpha: 1 });
  return tl;
}

function flowersBloom(target) {
  const tl = gsap.timeline({ delay: 0.5 });
  const flowers = target.querySelectorAll("[id^=flower-]");
  const buds = target.querySelectorAll("[id^=bud-]");
  const blooms = target.querySelectorAll("[id^=bloom-]");
  const petals = target.querySelectorAll("[id^=petal-]");
  tl.to([...flowers, ...buds, ...blooms], {
    scale: 1,
    duration: 2,
    ease: "back.out(2)",
    stagger: 0.5,
  })
    .to(flowers, { rotation: 45, duration: 3, ease: "sine.out" }, 0)
    .to(petals, { fill: "#e43b72", duration: 1 }, 0);
  return tl;
}

function currentBranchSwaying(target) {
  const tl = gsap.timeline({ yoyo: true, repeat: -1 });
  let rotation = 10;
  const pos = target.getAttribute("data-position");
  if (pos === "left") rotation = -10;
  else if (pos === "right") rotation = 5;
  tl.to(target, {
    rotation,
    duration: 2 + Math.random(),
    ease: "sine.inOut",
    repeat: -1,
    yoyo: true,
  });
  return tl;
}

function wholeBranchGrowIn(branches) {
  const tl = gsap.timeline();
  branches.forEach((branch, i) => {
    tl.to(
      branch,
      {
        scale: 1,
        duration: 3,
        ease: "power1.out",
        onStart: () => flowersBloom(branch),
        onComplete: () => currentBranchSwaying(branch),
      },
      i * 0.25
    );
  });
  return tl;
}

function smallBranchesSway() {
  const smallBranches = getSmallBranches();
  const tl = gsap.timeline({ yoyo: true, repeat: -1 });
  tl.to(smallBranches, {
    rotation: 5,
    duration: 2 + Math.random(),
    ease: "sine.inOut",
    stagger: Math.random() / 1.2,
  });
  // 可根据需要为特定分支单独设置 transformOrigin
  return tl;
}

onMounted(() => {
  const branches = getBranches();
  masterTimeline = gsap.timeline();
  masterTimeline
    .add(mainSetUp())
    .add(wholeBranchGrowIn(branches))
    .add(smallBranchesSway());
});

onUnmounted(() => {
  if (masterTimeline) masterTimeline.kill();
});
</script>
<style>
.content {
  overflow: hidden;
  height: 100vh;
}
</style>
